def fibonacci(n):
    # initial cases
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        # initialize sequence
        fib_seq = [0, 1]
        # calculate rest of the sequence
        for i in range(2, n + 1):
            fib_seq.append(fib_seq[i - 1] + fib_seq[i - 2])
        return fib_seq[-1]

