    assembler: An assembler object, which has the following attributes: attention_to_detail, technical_skills, problem_solving, manual_dexterity.
    """

    # Define the attribute averages and boundaries
    attribute_averages = {
        'attention_to_detail': 7,
        'technical_skills': 8,
        'problem_solving': 9,
        'manual_dexterity': 6,
    }
    attribute_boundaries = {
        'attention_to_detail': 4,
        'technical_skills': 5,
        'problem_solving': 5,
        'manual_dexterity': 4,
    }

    # Initialize score
    score = 0

    # Evaluate each attribute
    for attr in attribute_averages:
        if assembler[attr] >= attribute_averages[attr]:
            score += assembler[attr] - attribute_averages[attr]
        else:
            score -= attribute_averages[attr] - assembler[attr]

        # Subtract points for low attribute scores
        if assembler[attr] < attribute_boundaries[attr]:
            score -= abs(attribute_boundaries[attr] - assembler[attr])

    return score

